package com.beeboee.magnot.client;import com.beeboee.magnot.region.FerrousRegion;import net.minecraft.world.phys.Vec3;import java.util.*;public final class ClientFerrousRegionStore{private static List<FerrousRegion> regions=List.of();private ClientFerrousRegionStore(){}public static void set(List<FerrousRegion> r){regions=List.copyOf(r);}public static void clear(){regions=List.of();}public static List<FerrousRegion> regions(){return regions;}public static Optional<FerrousRegion> selected(Vec3 a,Vec3 b){FerrousRegion best=null;double d=Double.MAX_VALUE;for(FerrousRegion r:regions){Optional<Double> h=r.hitDistanceSqr(a,b);if(h.isPresent()&&h.get()<d){d=h.get();best=r;}}return Optional.ofNullable(best);}}
